from __future__ import annotations

from pathlib import Path

from tools.v4_exact_branch_bound_patch_temp import main as apply_branch_bound

PATH = Path("src/engines/v4_full_universe_package_search_core.py")
SEARCH_DEF = "def search_full_universe_packages(\n    candidates: list[Candidate],\n"


def main() -> None:
    apply_branch_bound()
    text = PATH.read_text(encoding="utf-8")
    old_imports = "from collections import Counter, defaultdict\nfrom itertools import combinations, permutations\nfrom typing import Any, Iterable, Iterator\n"
    new_imports = "from collections import Counter, defaultdict\nfrom concurrent.futures import ProcessPoolExecutor\nfrom itertools import combinations, permutations\nfrom math import comb\nfrom multiprocessing import get_context\nimport os\nfrom typing import Any, Iterable, Iterator\n"
    if old_imports not in text:
        raise SystemExit("parallel import target missing")
    text = text.replace(old_imports, new_imports, 1)

    insert_at = text.index(SEARCH_DEF)
    helpers = '''_PARALLEL_SEARCH_CONTEXT: dict | None = None\n\n\ndef _search_diag_template() -> dict:\n    return {"search_nodes": 0, "incoming_combinations_considered": 0, "packages_evaluated": 0, "packages_rejected_by_budget": 0, "packages_rejected_by_budget_bound": 0, "packages_rejected_by_club_limit": 0, "packages_rejected_by_legality": 0, "packages_dominated_on_frontier": 0, "packages_pruned_by_admissible_branch_bound": 0, "exact_utility_evaluations": 0, "exact_utility_pruned_by_admissible_bound": 0}\n\n\ndef _merge_numeric_diagnostics(target: dict, source: dict) -> None:\n    for key, value in source.items():\n        if not isinstance(value, bool) and isinstance(value, (int, float)):\n            target[key] = target.get(key, 0) + value\n\n\ndef _parallel_search_shard(jobs):\n    ctx = _PARALLEL_SEARCH_CONTEXT\n    if ctx is None:\n        raise RuntimeError("parallel package-search context not initialized")\n    current, by_id, pools = ctx["current"], ctx["by_id"], ctx["pools"]\n    baseline_profile, baseline_metrics = ctx["baseline_profile"], ctx["baseline_metrics"]\n    locked, policy, risk_by_element = ctx["locked"], ctx["policy"], ctx["risk_by_element"]\n    top_per_size, frontier_epsilon, position_extrema, roll = ctx["top_per_size"], ctx["frontier_epsilon"], ctx["position_extrema"], ctx["roll"]\n    diagnostics = _search_diag_template()\n    local_top = {k: [] for k in range(1, int(ctx["max_replacements"]) + 1)}\n    local_frontier = [_compact_for_frontier(roll)]\n    keep_profile_cache, chosen_profile_cache, incoming_risk_cache, position_prefix_cache = {}, {}, {}, {}\n    for k, out_ids in jobs:\n        outs = tuple(by_id[element] for element in out_ids)\n        out_set = set(out_ids)\n        keep = tuple(player for player in current if player.element not in out_set)\n        need = Counter(player.position for player in outs)\n        keep_profile = keep_profile_cache.setdefault(out_ids, _keep_profile_from_baseline(baseline_profile, outs))\n        outgoing_risk = _risk_aggregate(outs, risk_by_element)\n        def prefix_prunable(chosen_prefix, remaining_need):\n            bound_vec, utility_upper = _admissible_prefix_bounds(chosen_prefix, remaining_need, outs=outs, outgoing_risk=outgoing_risk, risk_by_element=risk_by_element, extrema=position_extrema, baseline_metrics=baseline_metrics, locked=locked, policy=policy, k=k)\n            frontier_blocked = any(_dominates_vector(_frontier_tuple(incumbent), bound_vec, frontier_epsilon) for incumbent in local_frontier)\n            if not frontier_blocked or len(local_top[k]) < top_per_size:\n                return False\n            return utility_upper + 1e-12 < _f(local_top[k][-1].get("adjusted_utility_gain_5"), float("-inf"))\n        for ins_raw in _incoming_combinations(pools, need, keep, ctx["derived_budget"], diagnostics, prefix_prunable=prefix_prunable):\n            ins = tuple(sorted(ins_raw, key=lambda row: (_POSITION_ORDER.get(row.position, 99), row.element)))\n            diagnostics["packages_evaluated"] += 1\n            in_ids = tuple(player.element for player in ins)\n            incoming_risk = incoming_risk_cache.get(in_ids)\n            if incoming_risk is None:\n                incoming_risk = _risk_aggregate(ins, risk_by_element); incoming_risk_cache[in_ids] = incoming_risk\n            cheap = _cheap_package_row(outs, ins, baseline_metrics, locked, policy, outgoing_risk, incoming_risk)\n            compact = _compact_for_frontier(cheap)\n            retained, removed = _frontier_insert(local_frontier, compact, 0.0)\n            diagnostics["packages_dominated_on_frontier"] += (0 if retained else 1) + (removed if retained else 0)\n            if not _can_enter_exact_top(cheap, local_top[k], top_per_size):\n                diagnostics["exact_utility_pruned_by_admissible_bound"] += 1; continue\n            chosen_profile = chosen_profile_cache.get(in_ids)\n            if chosen_profile is None:\n                chosen_profile = _chosen_profile(ins); chosen_profile_cache[in_ids] = chosen_profile\n            exact = _exactify_package(cheap, _metrics_from_profiles(keep_profile, chosen_profile, position_prefix_cache=position_prefix_cache), baseline_metrics)\n            diagnostics["exact_utility_evaluations"] += 1\n            _retain_top(local_top[k], exact, top_per_size)\n    return {"top_by_k": local_top, "frontier": [row for row in local_frontier if row.get("package_id") != "ROLL_BASELINE"], "diagnostics": diagnostics}\n\n\ndef _outgoing_job_cost(job, by_id, pools):\n    need = Counter(by_id[element].position for element in job[1]); estimate = 1\n    for pos, count in need.items():\n        if len(pools.get(pos, ())) < count: return 0\n        estimate *= comb(len(pools.get(pos, ())), int(count))\n    return estimate\n\n\ndef _balanced_outgoing_shards(jobs, workers, by_id, pools):\n    workers = max(1, min(int(workers), len(jobs))); shards = [[] for _ in range(workers)]; loads = [0] * workers\n    for job in sorted(jobs, key=lambda j: (_outgoing_job_cost(j, by_id, pools), j[0], j[1]), reverse=True):\n        idx = min(range(workers), key=lambda i: (loads[i], i)); shards[idx].append(job); loads[idx] += _outgoing_job_cost(job, by_id, pools)\n    return [tuple(shard) for shard in shards if shard]\n\n'''
    text = text[:insert_at] + helpers + text[insert_at:]

    search_at = text.index(SEARCH_DEF)
    body_at = text.index(") -> dict:\n", search_at) + len(") -> dict:\n")
    text = text[:body_at] + "    global _PARALLEL_SEARCH_CONTEXT\n" + text[body_at:]
    start = "    keep_profile_cache: dict[tuple[int, ...], dict] = {}\n"
    end = "    frontier.sort(key=_rank, reverse=True)\n"
    a, b = text.index(start, body_at), text.index(end, body_at)
    parallel_block = '''    position_extrema = _build_position_extrema(pools, risk_by_element, max_replacements)\n    all_jobs = []\n    for k in range(1, max_replacements + 1):\n        for outs_raw in combinations(current, k):\n            outs = tuple(sorted(outs_raw, key=lambda row: (_POSITION_ORDER.get(row.position, 99), row.element)))\n            all_jobs.append((k, tuple(player.element for player in outs)))\n    workers = min(max(1, int(search_cfg.get("parallel_shards") or 4)), max(1, int(os.cpu_count() or 1)), len(all_jobs))\n    shards = _balanced_outgoing_shards(all_jobs, workers, by_id, pools)\n    diagnostics["parallel_shards"], diagnostics["outgoing_jobs"] = len(shards), len(all_jobs)\n    _PARALLEL_SEARCH_CONTEXT = {"current": current, "by_id": by_id, "pools": pools, "derived_budget": derived_budget, "baseline_profile": baseline_profile, "baseline_metrics": baseline_metrics, "locked": locked, "policy": policy, "risk_by_element": risk_by_element, "top_per_size": top_per_size, "frontier_epsilon": frontier_epsilon, "position_extrema": position_extrema, "roll": roll, "max_replacements": max_replacements}\n    try:\n        if len(shards) <= 1 or not hasattr(os, "fork"):\n            shard_results = [_parallel_search_shard(shard) for shard in shards]\n        else:\n            with ProcessPoolExecutor(max_workers=len(shards), mp_context=get_context("fork")) as executor:\n                shard_results = list(executor.map(_parallel_search_shard, shards))\n    finally:\n        _PARALLEL_SEARCH_CONTEXT = None\n    for result in shard_results:\n        _merge_numeric_diagnostics(diagnostics, result.get("diagnostics") or {})\n        for k in range(1, max_replacements + 1):\n            for row in (result.get("top_by_k") or {}).get(k, []): _retain_top(top_by_k[k], row, top_per_size)\n        for compact in result.get("frontier") or []:\n            retained, removed = _frontier_insert(frontier, compact, frontier_epsilon)\n            diagnostics["packages_dominated_on_frontier"] += (0 if retained else 1) + (removed if retained else 0)\n    for k in range(1, max_replacements + 1): best_by_k[str(k)] = top_by_k[k][0] if top_by_k[k] else None\n\n'''
    text = text[:a] + parallel_block + text[b:]
    old = '            "branch_pruning_requires_frontier_and_top_impossibility": True,\n'
    if old not in text: raise SystemExit("parallel governance target missing")
    text = text.replace(old, old + '            "parallel_outgoing_shards_preserve_exact_union": True,\n            "local_frontier_uses_zero_epsilon_before_canonical_merge": True,\n', 1)
    PATH.write_text(text, encoding="utf-8")


if __name__ == "__main__": main()
